-- First run 20261013034836_basket_photo_ocr_db.version-check.sql and require known PostgreSQL 16+.
-- Read-only API requests may run as a read-only role: read pg_constraint (information_schema hides
-- tables owned by other roles) and name the apply executor postgres instead of current_user.
-- Aggregate SELECT only. Snapshot supplies full definitions, especially triggers.
select 'UTF8 encoding' item,case when current_setting('server_encoding')='UTF8' then '예' else '아니오' end value
union all select 'PostgreSQL 16+ catalog prerequisite',case when current_setting('server_version_num')::integer>=160000 then '예'else '아니오'end
union all select 'prerequisite recorded',case when (select count(*) from supabase_migrations.schema_migrations where version='20261012100000' and name='basket_link_view_db')=1 then '예' else '아니오' end
union all select 'new migration absent',case when not exists(select 1 from supabase_migrations.schema_migrations where version='20261013034836') then '예' else '아니오' end
union all select 'supported function defaults',case when not exists(select 1 from pg_default_acl where defaclrole='postgres'::regrole and defaclobjtype='f' and (defaclnamespace=0 or defaclnamespace='public'::regnamespace)and not(defaclacl <@ array[('postgres'::text||'=X/'||'postgres'::text)::aclitem,('=X/'||'postgres'::text)::aclitem,('anon=X/'||'postgres'::text)::aclitem,('authenticated=X/'||'postgres'::text)::aclitem,('service_role=X/'||'postgres'::text)::aclitem]))then '예'else '아니오'end
union all select 'auth execution paths supported',case when not exists(select 1 from pg_auth_members where roleid='authenticated'::regrole and member<>'postgres'::regrole and (inherit_option or member not in(select oid from pg_roles where rolname in('authenticator','supabase_realtime_admin') and not rolinherit)))then '예'else '아니오'end
union all select 'finite note versions',case when not exists(select 1 from public.app_notes where updated_at in('infinity'::timestamptz,'-infinity'::timestamptz))then '예'else '아니오'end
union all select 'notes triggers absent',case when not exists(select 1 from pg_trigger where tgrelid='public.app_notes'::regclass and not tgisinternal) then '예' else '아니오' end
union all select 'exact old CHECK intact',case when (select count(*) from pg_constraint where connamespace='public'::regnamespace and conname='app_notes_attachments_check')=1 and exists(select 1 from pg_constraint where conrelid='public.app_notes'::regclass and conname='app_notes_attachments_check' and contype='c' and convalidated) and exists(select 1 from pg_constraint where conrelid='public.app_notes'::regclass and conname='app_notes_attachments_check' and contype='c' and convalidated
 and btrim(regexp_replace(pg_get_constraintdef(oid),'\s+',' ','g'))=btrim(regexp_replace('CHECK ('||'
CASE
    WHEN (jsonb_typeof(attachments) = ''array''::text) THEN ((jsonb_array_length(attachments) <= 20) AND (NOT jsonb_path_exists(attachments, ''strict $[*]?(@.type() != "object")''::jsonpath)) AND (NOT jsonb_path_exists(attachments, ''$[*]?((((((((((((((@.type() != "object" || !(exists (@."drive_file_id"))) || !(exists (@."file_name"))) || !(exists (@."mime_type"))) || !(exists (@."size_bytes"))) || @."drive_file_id".type() != "string") || !(@."drive_file_id" like_regex "^[A-Za-z0-9_-]{1,255}$")) || @."file_name".type() != "string") || !(@."file_name" like_regex "^.{1,255}$" flag "s")) || @."mime_type".type() != "string") || !(@."mime_type" like_regex "^[^/[:space:]]{1,127}/[^/[:space:]]{1,127}$")) || @."size_bytes".type() != "number") || @."size_bytes" < 1) || @."size_bytes" > 104857600) || @."size_bytes" != @."size_bytes".floor())''::jsonpath)) AND (NOT jsonb_path_exists(attachments, ''$[*].keyvalue()?(((@."key" != "drive_file_id" && @."key" != "file_name") && @."key" != "mime_type") && @."key" != "size_bytes")''::jsonpath)))
    ELSE false
END'||')','\s+',' ','g'))) then '예' else '아니오' end
union all select 'OCR RPC name absent',case when not exists(select 1 from pg_proc p join pg_namespace s on s.oid=p.pronamespace where s.nspname='public' and p.proname='app_basket_update_attachment_ocr') then '예' else '아니오' end
union all select 'OCR attachment count',count(*)::text from public.app_notes n cross join lateral jsonb_array_elements(n.attachments)a where a ? 'ocr'
union all select 'notes rows',count(*)::text from public.app_notes
union all select 'notes full-row hash',md5(coalesce(string_agg((to_jsonb(n)||jsonb_build_object('occurred_at',to_char(n.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'created_at',to_char(n.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char(n.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'archived_at',to_char(n.archived_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')))::text,E'\n' order by id),'')) from public.app_notes n
union all select 'links full-row hash',md5(coalesce(string_agg((to_jsonb(l)||jsonb_build_object('created_at',to_char(l.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'task_checked_at',to_char(l.task_checked_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')))::text,E'\n' order by id),'')) from public.app_record_links l
union all select 'notes owner RLS',case when exists(select 1 from pg_class c join pg_policy p on p.polrelid=c.oid where c.oid='public.app_notes'::regclass and c.relrowsecurity and p.polname='notes_owner_all') then '예' else '아니오' end
union all select 'owner policy hash',md5(coalesce(string_agg(polname||':'||polcmd::text||':'||polroles::text||':'||coalesce(pg_get_expr(polqual,polrelid),'')||':'||coalesce(pg_get_expr(polwithcheck,polrelid),''),E'\n' order by polname),'')) from pg_policy where polrelid in('public.app_notes'::regclass,'public.app_record_links'::regclass)
union all select 'notes links ACL hash',md5(coalesce(string_agg(relname||':'||relrowsecurity::text||':'||relforcerowsecurity::text||':'||coalesce(relacl::text,''),E'\n' order by relname),'')) from pg_class where oid in('public.app_notes'::regclass,'public.app_record_links'::regclass)
union all select 'existing function hash',md5(coalesce(string_agg(pg_get_functiondef(p.oid)||':'||coalesce(p.proacl::text,''),E'\n' order by p.proname),'')) from pg_proc p where p.oid in(to_regprocedure('public.app_basket_confirm_links(uuid,timestamptz,jsonb)'),to_regprocedure('public.app_basket_update_link_summary(uuid,text,text)'));
